import math
from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def get_divisors(n):
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)
        i += 1
    return sorted([d for d in divisors if d > 1])

def count_prime_factors(n):
    original = n
    count = 0
    d = 2
    while d * d <= n:
        if n % d == 0:
            while n % d == 0:
                count += 1
                n //= d
        d += 1
    if n > 1:
        count += 1
    return count

def prime_factors_process(n):
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors

def build_divisors_sequence(n):
    divisors = get_divisors(n)
    if not divisors:
        return divisors, 0

    pfs = prime_factors_process(n)

    # Check if all divisors share a common prime factor
    first = divisors[0]
    common_factors = set()
    d = 2
    while d * d <= first:
        if first % d == 0:
            common_factors.add(d)
        d += 1
    if first > 1:
        common_factors.add(first)

    common_in_all = True
    for div in divisors:
        has_common = False
        for p in common_factors:
            if div % p == 0:
                has_common = True
                break
        if not has_common:
            common_in_all = False
            break

    # If all divisors share a prime factor, 0 moves is possible
    if common_in_all:
        return divisors, 0

    # Special case: n = p^k, all divisors share p
    if len(pfs) == 1:
        return divisors, 0

    # Otherwise, try to find arrangement with minimal coprime pairs
    # Try ordering by factor grouping
    if len(divisors) <= 2:
        return divisors, 1 if divisors else 0

    # Simple heuristic: order by divisibility relationships
    sorted_divs = sorted(divisors)
    return sorted_divs, 1

def main_solution(input_string):
    lines = input_string.strip().split('\n')
    t = int(lines[0])
