from collections import Counter

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    graph = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            count = 0
            stack = [i]
            while stack:
                node = stack.pop()
                if visited[node]:
                    continue
                visited[node] = True
                count += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
            components.append(count)

    if not components:
        return '2\n'

    # Check if any component is already lucky
    def is_lucky(num):
        s = str(num)
        for c in s:
            if c not in {'4', '7'}:
                return False
        return True

    for comp in components:
        if is_lucky(comp):
            return '0\n'

    # Generate lucky numbers up to n
    def generate_lucky_numbers(limit):
        lucky = []
        def dfs(current):
            if current > limit:
                return
            if current > 0:
                lucky.append(current)
            if current * 10 + 4 <= limit:
                dfs(current * 10 + 4)
            if current * 10 + 7 <= limit:
                dfs(current * 10 + 7)
        dfs(0)
        return sorted(lucky)

    lucky_numbers = generate_lucky_numbers(n)

    # DP to find minimum number of components needed for each sum
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0

    component_counts = Counter(components)
    distinct_sizes = sorted(component_counts.keys())

    for size in distinct_sizes:
        count = component_counts[size]
        for i in range(min(count, 10001)):
            for s in range(n, size - 1, -1):
                dp[s] = min(dp[s], dp[s - size] + 1)

    min_roads = INF
    for lucky in lucky_numbers:
        if dp[lucky] != INF:
            min_roads = min(min_roads, dp[lucky] - 1)

    if min_roads == INF:
        return '-1\n'

    return str(min_roads) + '\n'
