        if n <= 2:
            return True

        # Check all zeros
        if all(x == 0 for x in seq):
            return True

        # Determine ratio from first two non-zero elements
        i = 0
        while i < n and seq[i] == 0:
            i += 1

        # If we can't find a non-zero element at the start
        if i >= n - 1 or seq[i + 1] == 0:
            return all(x == 0 for x in seq)

        # Calculate ratio
        r = seq[i + 1] / float(seq[i])

        # Check remaining elements
        for j in range(i + 2, n):
            if seq[j] == 0:
                # If we encounter a zero after a non-zero, it breaks GP (unless all are zero)
                return False
            if abs(seq[j] - seq[j-1] * r) > 1e-9:
                return False

        return True

    # First check if already GP
    if is_gp(arr):
        return "0"

    # Try removing each element
    for i in range(n):
        sub = arr[:i] + arr[i+1:]
        if is_gp(sub):
            return "1"

    return "2"
