from collections import deque
import sys

sys.setrecursionlimit(10000)

def solve(n, m, a, b, edges):
    # Build adjacency list
    adj = [[False] * (n + 1) for _ in range(n + 1)]
    for p, q in edges:
        adj[p][q] = adj[q][p] = True

    # Build flow network
    # Source = 0, Cities = 1..n, Sink = n+1
    source = 0
    sink = n + 1
    num_nodes = n + 2

    capacity = {}

    def add_edge(u, v, cap):
        if (u, v) not in capacity:
            capacity[(u, v)] = 0
        capacity[(u, v)] += cap
        if (v, u) not in capacity:
            capacity[(v, u)] = 0

    # Source to each city i with capacity a[i-1]
    for i in range(1, n + 1):
        add_edge(source, i, a[i - 1])

    # Each city i to sink with capacity b[i-1]
    for i in range(1, n + 1):
        add_edge(i, sink, b[i - 1])

    # Edges between cities: from city i to city j if they're connected or same city
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j or adj[i][j]:
                add_edge(i, j, 1)  # max 1 soldier per road usage (simplified)

    def bfs(parent):
        visited = [False] * num_nodes
        queue = deque()
        queue.append(source)
        visited[source] = True
        parent[source] = -1

        while queue:
            u = queue.popleft()
            for v in range(num_nodes):
                if not visited[v] and capacity.get((u, v), 0) > 0:
                    visited[v] = True
                    parent[v] = u
                    if v == sink:
                        return True
                    queue.append(v)
        return False

    def dfs(u, flow, parent):
        if u == sink:
