from functools import lru_cache

def solution(board_str):
    lines = board_str.strip().split('\n')
    n = 5

    # Parse board and identify chocolate positions
    chocolates = []  # List of (row, col) where chocolates exist

    for row in range(n):
        parts = lines[row].split()
        for col in range(len(parts)):
            if parts[col] == 'O':
                chocolates.append((row, col))

    num_chocolates = len(chocolates)

    if num_chocolates == 0:
        return "Lillebror\n"

    @lru_cache(maxsize=None)
    def can_win(state):
        """Returns True if current player can win from this state"""
        if state == 0:
            return False  # No moves possible, current player loses

        for i in range(num_chocolates):
            if state & (1 << i):  # If chocolate i is still there
                r, c = chocolates[i]

                # 6 directions in hexagonal grid
                directions = [(-1, 0), (0, -1), (1, -1), (1, 0), (0, 1), (-1, 1)]

                for dr, dc in directions:
                    chain = [i]
                    curr_r, curr_c = r, c

                    # Follow the direction to find consecutive chocolates
                    while True:
                        next_r, next_c = curr_r + dr, curr_c + dc

                        # Check bounds
                        if next_r < 0 or next_r >= n:
                            break

                        if next_c < 0 or next_c >= len(lines[next_r]):
                            break

                        # Check if there's a chocolate at the next position
                        next_pos = (next_r, next_c)
                        if next_pos in chocolates:
                            next_idx = next_pos in chocolates
                            if next_idx == list(chocolates).index(next_pos):
                                next_idx = chocolates.index(next_pos)
                                if state & (1 << next_idx):
                                    chain.append(next_idx)
                                    curr_r, curr_c = next_r, next_c
                                else:
                                    break
                            elif next_idx == -1:
                                break
                        else:
                            break

                    # Try removing all chocolates in the chain
                    if len(chain) > 1:
                        new_state = state
                        for idx in chain:
                            new_state &= ~(1 << idx)

                        if not can_win(new_state):
                            return True

        return False

    initial_state = 0
    for i in range(num_chocolates):
        initial_state |= (1 << i)

    return "Karlsson\n" if can_win(initial_state) else "Lillebror\n"


