        current_count = 1

        # Merge segments while current element is less than top of stack
        while stack and current_sum / current_count < stack[-1][0]:
            avg, count = stack.pop()
            current_sum += avg * count
            current_count += count

        stack.append((current_sum / current_count, current_count))

    # Reconstruct the result
    result_lines = []
    for avg, count in stack:
        # Print each element in the segment
        line_val = avg
        result_lines.append(f"{line_val:.15g}")

    print('\n'.join(result_lines))
    return '\n'.join(result_lines)
