    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for ai, bi, direction in constraints:
        if direction == 'LEFT':
            adj[bi].append(ai)
            in_degree[ai] += 1
        else:
            adj[ai].append(bi)
            in_degree[bi] += 1

    topo_order = []
    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]

    if not queue:
        if any(in_degree[i] > 0 for i in range(1, n + 1)):
            return "IMPOSSIBLE\n"

    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topo_order) != n:
        return "IMPOSSIBLE\n"

    pos = {node: i for i, node in enumerate(topo_order)}

    for ai, bi, direction in constraints:
        if pos.get(bi, -1) < pos.get(ai, -1):
            if direction != 'LEFT':
                return "IMPOSSIBLE\n"
        else:
            if direction != 'RIGHT':
                return "IMPOSSIBLE\n"

