def solution(input_str):
    lines = input_str.strip().split('\n')
    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    m, n, p = len(s1), len(s2), len(virus)

    if p == 0:
        return "0"

    # KMP prefix function for virus
    pi = [0] * p
    j = 0
    for i in range(1, p):
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # KMP transition: what's the new KMP state after seeing character c?
    def kmp_next(k, c):
        while k > 0 and c != virus[k]:
            k = pi[k-1]
        if c == virus[k]:
            k += 1
        return k

    # dp[i][j][k] = max length of LCS using s1[:i], s2[:j] ending with virus state k
    dp = [[[-1] * p for _ in range(n + 1)] for _ in range(m + 1)]
    dp[0][0][0] = 0

    # Parent for reconstruction: (type, prev_i, prev_j, prev_k)
    par = [[[None] * p for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            for k in range(p):
                if dp[i][j][k] == -1:
                    continue

                current_len = dp[i][j][k]

                # Skip s1[i]
                if i < m:
                    if dp[i+1][j][k] < current_len:
                        dp[i+1][j][k] = current_len
                        par[i+1][j][k] = ('S1', i, j, k)

                # Skip s2[j]
                if j < n:
                    if dp[i][j+1][k] < current_len:
                        dp[i][j+1][k] = current_len
                        par[i][j+1][k] = ('S2', i, j, k)

                # Match
                if i < m and j < n and s1[i] == s2[j]:
                    prev_k = k
                    new_k = kmp_next(prev_k, s1[i])
                    if new_k < p:  # Don't complete virus as substring
                        if dp[i+1][j+1][new_k] < current_len + 1:
                            dp[i+1][j+1][new_k] = current_len + 1
                            par[i+1][j+1][new_k] = ('MATCH', i, j, prev_k)

    # Find best result
    best_len = 0
    best_k = 0
    for k in range(p):
        if dp[m][n][k] > best_len:
            best_len = dp[m][n][k]
            best_k = k

    if best_len == 0:
        return "0"

    # Reconstruct the solution
    i, j, k = m, n, best_k
    res = []

    while True:
        p_state = par[i][j][k]
        if p_state is None:
            break

        op, pi, pj, pk = p_state

        if op == 'MATCH':
            res.append(s1[pi])
            i, j, k = pi - 1, pj - 1, pk
        elif op == 'S1':
            i, j, k = pi - 1, j, k
        else:  # S2
            i, j, k = i, pj - 1, pk

    return ''.join(reversed(res))
