    first_combinations = []
    for bits in product([0, 1], repeat=first_half_len):
        first_bits = ''.join(str(b) for b in bits)
        first_combinations.append(first_bits)

    # Generate all combinations for second half
    second_combinations = []
    for bits in product([0, 1], repeat=second_half_len):
        second_bits = ''.join(str(b) for b in bits)
        second_combinations.append(second_bits)

    count = 0

    for f_bits in first_combinations:
        for s_bits in second_combinations:
            code = f_bits + s_bits
            if is_valid(code, attempts):
                count += 1

    return str(count)
