import sys

def solve_food_assignment():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    pairs = []
    boy_positions = {}
    girl_positions = {}

    for i in range(n):
        a = int(next(iterator))
        b = int(next(iterator))
        pairs.append((a, b, i + 1))
        boy_positions[a] = b
        girl_positions[b] = a

    food = [0] * (2 * n + 1)
    is_valid = True

    def check_assignment():
        for i in range(2 * n):
            c1 = (i % (2 * n)) + 1
            c2 = ((i + 1) % (2 * n)) + 1
            c3 = ((i + 2) % (2 * n)) + 1
            if food[c1] == food[c2] == food[c3]:
                return False
        return True

    def assign_pair(boy, girl):
        if food[boy] != 0 and food[girl] != 0:
            return food[boy] != food[girl]
        if food[boy] != 0:
            food[girl] = 3 - food[boy]
            return check_assignment()
        if food[girl] != 0:
            food[boy] = 3 - food[girl]
            return check_assignment()
