def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    poly = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        poly.append((x, y))

    MOD = 1000000007

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def segments_intersect(a, b, c, d):
        """Check if segment ab and segment cd intersect strictly in their interiors."""
        cp1 = cross_product(a, b, c)
        cp2 = cross_product(a, b, d)
        cp3 = cross_product(c, d, a)
        cp4 = cross_product(c, d, b)

        return (cp1 * cp2 < 0) and (cp3 * cp4 < 0)

    def is_valid_diagonal(i, j):
        """Check if diagonal from vertex i to vertex j doesn't cross polygon boundary."""
        # Check if i and j are consecutive
        diff = (j - i) % n
        if diff == 1 or i - j == 0 or diff == 0:
            return True

        for k in range(n):
            next_k = (k + 1) % n
            # Skip edges incident to i or j
            if k == i or next_k == i or k == j or next_k == j:
                continue
            if segments_intersect(poly[i], poly[j], poly[k], poly[next_k]):
                return False
        return True

    dp = [[0] * n for _ in range(n)]

    # Base case: triangles (3 consecutive vertices) have 1 triangulation
    for i in range(n):
        j = (i + 2) % n
        if is_valid_diagonal(i, j):
            dp[i][j] = 1

    # Fill DP for larger subpolygons
    for length in range(2, n):  # length = j - i in terms of steps
        for i in range(n):
            j = (i + length) % n

            # Try all possible intermediate vertices k to form triangle (i, k, j)
            for k in range(n):
                # k should be between i and j (in clockwise order)
                sk = (k - i) % n
                sj = (j - i) % n
                if 0 < sk < sj:
                    # We need diagonals (i,k) and (k,j) to be valid
                    if is_valid_diagonal(i, k) and is_valid_diagonal(k, j):
                        dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    # Answer is triangulation count for the full polygon (0 to n-1)
    return str(dp[0][n - 1])
