        # lanterns are 1-indexed in problem, 0-indexed in our code
        directions = [''] * n  # 'L' or 'R'
        satisfied = [False] * n

        # We'll try a greedy approach: process from left to right
        # For each lantern, if not yet satisfied, we'll try to satisfy it
        # and also ensure it can satisfy others if possible

        # First pass: try to satisfy lanterns going left
        for i in range(n - 1, -1, -1):
            if not satisfied[i]:
                # Try to satisfy lantern i by making some lantern to its right point left
                # or some lantern to its left point right
                found = False

                # Check if we can be illuminated from the right
                if not found:
                    for j in range(i + 1, min(i + p[i] + 1, n)):
                        if not satisfied[j] and directions[j] == '':
                            # j can illuminate i if j points left and p[j] >= (j - i)
                            if j - i <= p[j]:
                                directions[j] = 'L'
                                satisfied[i] = True
                                satisfied[j] = False  # j is being used to illuminate i
                                found = True
                                break

