def try_sequence(a, b, sa, sb):
    n = sa + sb
    if n == 0:
        return []

    from collections import deque
    visited = set()
    queue = deque([(0, 0, 0, 0, [])])

    while queue:
        idx, rem_a, rem_b, won_a, won_b, path = queue.popleft()
        state = (idx, rem_a, rem_b, won_a, won_b)
        if state in visited:
            continue
        visited.add(state)

        if idx == n:
            if rem_a == 0 and rem_b == 0 and won_a == sa and won_b == sb:
                return path
            continue

        # Try A wins
        for wa in range(25 if idx < 4 else 15, 29):
            if wa > rem_a:
                continue
            for wb in range(0, 25):
                if wb > rem_b:
                    break
                if wa - wb < 2:
                    continue
                next_state = (idx + 1, rem_a - wa, rem_b - wb, won_a + 1, won_b)
                queue.append((idx + 1, rem_a - wa, rem_b - wb, won_a + 1, won_b, [(wa, wb)] + path))

        # Try B wins
        for wb in range(25 if idx < 4 else 15, 29):
            if wb > rem_b:
                continue
            for wa in range(0, 25):
                if wa > rem_a:
                    break
                if wb - wa < 2:
                    continue
                next_state = (idx + 1, rem_a - wa, rem_b - wb, won_a, won_b + 1)
                queue.append((idx + 1, rem_a - wa, rem_b - wb, won_a, won_b + 1, [(wa, wb)] + path))

    return None
