def solution(input_str):
    """
    Solves the problem by finding two strings s1 (length n) and s2 (length m)
    such that sk (generated by sn = sn-2 + sn-1) has exactly x occurrences of "AC".
    """
    k, x, n, m = map(int, input_str.strip().split())

    def compute_ac_count(a1, a2, start_s1, end_s1, start_s2, end_s2):
        """Compute AC count in sk given base string AC counts and boundary conditions."""
        a = [0] * (k + 1)
        a[1] = a1
        a[2] = a2

        # For i >= 3, s_i = s_{i-2} + s_{i-1}
        # The number of AC occurrences is: a[i-2] + a[i-1] + boundary_effect
        # Boundary effect: 1 if s_{i-2} ends with 'A' and s_{i-1} starts with 'C'

        # For i = 3: s3 = s1 + s2, boundary between s1 and s2
        # For i = 4: s4 = s2 + s3, boundary between s2 and s3
        # For i >= 5: pattern stabilizes
        #   - If i is odd: s_i = s_{i-2} + s_{i-1}, boundary between strings ending with end_s2 and starting with start_s2
        #   - If i is even: s_i = s_{i-2} + s_{i-1}, boundary between strings ending with end_s2 and starting with start_s1

        for i in range(3, k + 1):
            if i == 3:
                b = 1 if end_s1 == 'A' and start_s2 == 'C' else 0
            elif i == 4:
                b = 1 if end_s2 == 'A' and start_s1 == 'C' else 0
            else:
                if i % 2 == 1:  # odd: s_i = s_{i-2} + s_{i-1} where s_{i-2} and s_{i-1} both end with end_s2
                    b = 1 if end_s2 == 'A' and start_s2 == 'C' else 0
                else:  # even
                    b = 1 if end_s2 == 'A' and start_s1 == 'C' else 0
            a[i] = a[i-2] + a[i-1] + b

        return a[k]

    def construct_s1(length, start, end, num_ac):
        """Construct s1 with given length, start/end characters, and AC count."""
        if num_ac == 0:
            if start == end:
                return start * length
            elif length == 1:
                return start
            else:
                return start + 'B' * max(0, length - 2) + end

        if length < 2 * num_ac:
            return construct_s1(length, start, end, num_ac - 1)

        if start == 'A' and end == 'C':
            s = "AC" * num_ac
            if len(s) > length:
                num_ac = length // 2
                s = "AC" * num_ac
        else:
            s = "AC" * num_ac
            if len(s) > length:
                num_ac = length // 2
                s = "AC" * num_ac

        if len(s) > length:
            return s[:length]
        s += 'B' * max(0, length - len(s))
        return s[:length]

    def construct_s2(length, start, end, num_ac):
        return construct_s1(length, start, end, num_ac)

    # Try all configurations
    chars = ['A', 'B', 'C', 'D']

    for start_s1 in chars:
        for end_s1 in chars:
            for start_s2 in chars:
                for end_s2 in chars:
                    max_a1 = min(n, 30)
                    max_a2 = min(m, 30)

                    for a1 in range(max_a1 + 1):
                        for a2 in range(max_a2 + 1):
                            result = compute_ac_count(a1, a2, start_s1, end_s1, start_s2, end_s2)
                            if result == x:
                                s1 = construct_s1(n, start_s1, end_s1, a1)
                                s2 = construct_s2(m, start_s2, end_s2, a2)
                                return f"{s1}\n{s2}\n"

    return "Happy new year!\n"
